-- Phase 46: preventive action tracking and management follow-up
create table if not exists public.election_preventive_actions(id uuid primary key default gen_random_uuid(),award_space_id uuid not null references public.award_spaces(id) on delete cascade,postmortem_id uuid not null references public.election_incident_postmortems(id) on delete cascade,incident_id uuid not null references public.election_incidents(id) on delete cascade,title text not null,description text not null,owner_id uuid references public.admins(id) on delete set null,target_date date not null,priority text not null default 'medium' check(priority in('low','medium','high','critical')),status text not null default 'open' check(status in('open','in_progress','completed','verified')),completion_note text,completed_at timestamptz,completed_by uuid references public.admins(id) on delete set null,verification_note text,verified_at timestamptz,verified_by uuid references public.admins(id) on delete set null,created_by uuid references public.admins(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists election_preventive_actions_followup_idx on public.election_preventive_actions(award_space_id,status,target_date,priority);
alter table public.election_preventive_actions enable row level security;
